```javascript
import Component from '@glimmer/component';
import { service } from '@glimmer/core';
import { action } from '@ember/tracked-decorator';
import { later } from '@ember/runloop';

export default class CsvDownloaderComponent extends Component {
  @service()
  worker;

  url = '';
  downloading = false;
  error = null;
  progress = 0;

  constructor() {
    super(...arguments);
  }

  @action
  startDownload() {
    this.error = null;
    this.downloading = true;
    this.progress = 0;

    this.worker.postMessage({
      url: this.url,
      type: 'download',
    });
  }

  @action
  stopDownload() {
    this.downloading = false;
    this.worker.postMessage({ type: 'terminate' });
  }

  didReceiveMessage(event) {
    const message = event.data;

    switch (message.type) {
      case 'progress':
        this.progress = message.progress;
        break;
      case 'success':
        this.downloading = false;
        // Trigger a download of the CSV data
        const blob = new Blob([message.data], { type: 'text/csv' });
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'data.csv'; // Or a more descriptive filename
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        window.URL.revokeObjectURL(url);
        break;
      case 'error':
        this.error = message.error;
        this.downloading = false;
        break;
    }
  }
}
